import React, { useState } from 'react';
import api from '../api/axios';
import { Container, Form, Button } from 'react-bootstrap';

const AdminPanel = () => {
  const [form, setForm] = useState({
    email: '',
    password: '',
    last_name: '',
    first_name: '',
    middle_name: '',
    position: ''
  });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleCreateTeacher = async (e) => {
    e.preventDefault();
    try {
      await api.post('/director/teacher', form);
      alert('Учитель создан');
      setForm({ email: '', password: '', last_name: '', first_name: '', middle_name: '', position: '' });
    } catch (err) {
      alert('Ошибка: ' + err.response?.data?.message);
    }
  };

  return (
    <Container className="mt-4">
      <h3>Админ-панель (Директор)</h3>
      <h5>Создать учителя</h5>
      <Form onSubmit={handleCreateTeacher}>
        <Form.Group className="mb-2">
          <Form.Control name="email" placeholder="Email" value={form.email} onChange={handleChange} required />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Control name="password" type="password" placeholder="Пароль" value={form.password} onChange={handleChange} required />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Control name="last_name" placeholder="Фамилия" value={form.last_name} onChange={handleChange} required />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Control name="first_name" placeholder="Имя" value={form.first_name} onChange={handleChange} required />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Control name="middle_name" placeholder="Отчество" value={form.middle_name} onChange={handleChange} />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Control name="position" placeholder="Должность" value={form.position} onChange={handleChange} required />
        </Form.Group>
        <Button type="submit" variant="primary">Создать</Button>
      </Form>
    </Container>
  );
};

export default AdminPanel;
